INSERT INTO `audit_logs` (`id`, `userId`, `action`, `entity`, `entityId`, `oldValue`, `newValue`, `ip`, `createdAt`) VALUES ('38fe695b-934a-4151-b420-a72d86153c59', 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', 'POST_V1', 'v1', 'bfbae981-57cf-4bc5-b22a-a69f4973b2ee', NULL, '{"id":"bfbae981-57cf-4bc5-b22a-a69f4973b2ee","title":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","description":"በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ","formSchema":{"titleAm":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","titleEn":"Volunteer Ministry Sign-Up Form","descriptionAm":"ለቤተ ክርስቲያንና ለወገን በበጎ ፈቃድ ለማገልገል ይመዝገቡ","descriptionEn":"Register to serve the church and community as a volunteer","fields":[{"name":"volunteerName","type":"text","labelAm":"የበጎ ፈቃደኛው ሙሉ ስም","labelEn":"Volunteer Full Name","required":true,"validation":{"minLength":3}},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true,"validation":{"minLength":9}},{"name":"profession","type":"text","labelAm":"የትምህርት ደረጃ ወይም ሙያዊ መስክ","labelEn":"Education or Profession","required":true},{"name":"interestedMinistries","type":"checkbox","labelAm":"ለማገልገል የሚፈልጓቸው ዘርፎች (ቢያንስ አንድ ይምረጡ)","labelEn":"Interested Ministry Fields","required":true,"options":[{"value":"media","labelAm":"ሚዲያ፣ ድረ-ገጽና ቴክኖሎጂ","labelEn":"Media & Technology"},{"value":"children","labelAm":"የሕፃናትና ታዳጊዎች ማስተማር","labelEn":"Children Teaching"},{"value":"cleaning_order","labelAm":"የቤተ መቅደስ ጽዳትና ሥርዓት ማስከበር","labelEn":"Sanctuary Care & Protocol"},{"value":"medical_aid","labelAm":"የሕክምናና የመጀመሪያ እርዳታ ድጋፍ","labelEn":"First Aid & Health Ministry"},{"value":"charity","labelAm":"የአረጋውያንና ችግረኞች መርጃ ማዕድ","labelEn":"Charity & Food Outreach"}],"validation":{"minSelected":1}},{"name":"availableDays","type":"checkbox","labelAm":"የሚያገለግሉባቸው አመቺ ቀናት","labelEn":"Available Days","required":true,"options":[{"value":"sat_afternoon","labelAm":"ቅዳሜ ከሰዓት","labelEn":"Saturday Afternoon"},{"value":"sun_morning","labelAm":"እሑድ ጠዋት","labelEn":"Sunday Morning"},{"value":"sun_afternoon","labelAm":"እሑድ ከሰዓት","labelEn":"Sunday Afternoon"},{"value":"holidays","labelAm":"በዓበይት በዓላት ቀናት","labelEn":"On Major Feast Days"}],"validation":{"minSelected":1}},{"name":"experienceSummary","type":"textarea","labelAm":"ቀደም ሲል የነበሩዎት የበጎ ፈቃድ ወይም የአገልግሎት ልምዶች","labelEn":"Previous Volunteer or Service Experience","required":true,"validation":{"minLength":10,"maxLength":1000}},{"name":"hasConfessionFather","type":"radio","labelAm":"የንስሐ አባት አሎት?","labelEn":"Do you have a confession father?","required":true,"options":[{"value":"yes","labelAm":"አዎ አለኝ","labelEn":"Yes"},{"value":"no","labelAm":"እስካሁን የለኝም","labelEn":"Not yet"}]},{"name":"recommendationLetter","type":"file","labelAm":"የድጋፍ ወይም የደብር ደብዳቤ (ካለዎት)","labelEn":"Recommendation Letter (Optional)","required":false}]},"status":"open","openUntil":null,"allowOneResponsePerMember":false,"createdBy":"cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1","createdAt":"2026-10-20T19:13:55.346Z","updatedAt":"2026-10-20T19:13:55.346Z"}', '127.0.0.1', '2026-10-20T19:13:55.431Z');
