INSERT INTO `events` (`id`, `title`, `description`, `location`, `startAt`, `endAt`, `capacity`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('953d4b63-f586-4f9e-a4ae-3f64deed9227', 'ዓመታዊ የአባላት መንፈሳዊ ጉዞ ( capacity = 2 )', 'ወደ ደብረ ሊባኖስ ገዳም የሚደረግ መንፈሳዊ ጉዞ', 'ደብረ ሊባኖስ', '2026-11-20T06:00:00.000Z', '2026-11-20T19:00:00.000Z', 2, '049b5097-0720-4f3d-97ea-f28d13c2af54', '2026-10-20T19:13:57.293Z', '2026-10-20T19:13:57.293Z');
INSERT INTO `events` (`id`, `title`, `description`, `location`, `startAt`, `endAt`, `capacity`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('c7d030d8-ce6a-4f18-a9a4-c46486a717b4', 'የወጣቶች መንፈሳዊ ሲምፖዚየም', 'ወጣቱ በዘመናዊው ዓለም ውስጥ ያለውን የክርስትና ማንነት ለመጠበቅ የሚደረግ ውይይት', 'የሰንበት ት/ቤት ትልቁ አዳራሽ', '2026-11-08T14:00:00.000Z', '2026-11-08T18:00:00.000Z', 150, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.963Z', '2026-10-17T17:56:56.963Z');
INSERT INTO `events` (`id`, `title`, `description`, `location`, `startAt`, `endAt`, `capacity`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('d8496316-c480-43e4-8dda-51c2ce679126', 'የቅዱስ ያሬድ መዝሙር ዝግጅት ኮንሰርት', 'በአዕማደ ሰላም መዘምራን የሚቀርብ ልዩ የያሬዳዊ ዜማና ዝማሬ ምሽት', 'የቤተ ክርስቲያኑ አውደ ምሕረት', '2026-11-22T16:00:00.000Z', '2026-11-22T20:00:00.000Z', 500, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:57.016Z', '2026-10-17T17:56:57.016Z');
INSERT INTO `events` (`id`, `title`, `description`, `location`, `startAt`, `endAt`, `capacity`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f9638824-54fc-4aa5-9ff8-6c861e1217d8', 'የሰንበት ትምህርት ቤት የምክክር ጉባኤ', 'የአስተዳደር አባላት፣ መምህራንና የአገልግሎት ክፍላት የጋራ ዓመታዊ የዕቅድ ጉባኤ', 'ዋናው የመሰብሰቢያ አዳራሽ', '2026-10-25T09:00:00.000Z', '2026-10-25T13:00:00.000Z', 100, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.915Z', '2026-10-17T17:56:56.915Z');
