INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('570dec9c-803d-42f2-aaf6-4bde1539b477', 'ጽዮን ሆይ ደስ ይበልሽ', 'ጽዮን ሆይ ደስ ይበልሽ ንጉሥሽ ይመጣል፤ ጻድቅና አዳኝ የሆነው ጌታ።', 7, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.802Z', '2026-10-17T17:56:56.802Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('598a85b6-c779-41ed-821f-dbe4b9739d91', 'ገብርኤል አብሳሪው', 'ብስራተ ሰላምን ይዞ የመጣው፤ ገብርኤል መልአከ እግዚአብሔር ነው።', 4, 'ዘማሪ ይስሐቅ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.742Z', '2026-10-17T17:56:56.742Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('611ac262-6954-4d2e-bd01-909fa29319fe', 'ቅዱስ ሚካኤል ሊቀ መላእክት', 'ቅዱስ ሚካኤል ቆሟል በፊታችን፤ ታዳጊ መልአክ ነው ለመከራችን።', 4, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.697Z', '2026-10-17T17:56:56.697Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('6d4ba5a0-2fab-4df8-b7ed-2b014150ae7e', 'ቸርነትህ ብዙ ነው', 'ቸርነትህ ብዙ ነው ምህረትህም አያልቅም፤ አቤቱ አምላካችን ስምህ የተመሰገነ ይሁን።', 1, 'ሊቀ መዘምራን ቴዎድሮስ ዮሴፍ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.675Z', '2026-10-17T17:56:56.675Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('764fd6d5-4c7a-4f9e-88e6-bf9d59317712', 'በጾም በጸሎት እንትጋ', 'በጾም በጸሎት ወደ አምላክ እንቅረብ፤ የልብ ንጽሕናን ከእርሱ እንቀበል።', 6, 'ዘማሪት ፋንቱ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.811Z', '2026-10-17T17:56:56.811Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('7d91963b-48ed-4672-8b9f-f1be8f4b3639', 'አቡነ አረጋዊ ዘደብረ ዳሞ', 'ዘንዶውን በገመድ አስይዞ የረዳህ፤ ደብረ ዳሞ ላይ በጸሎት የጸናህ።', 5, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.785Z', '2026-10-17T17:56:56.785Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('9848a547-6d41-4f9d-bdbb-67101902e3ee', 'ነፍሴ ሆይ እግዚአብሔርን ባርኪ', 'ነፍሴ ሆይ እግዚአብሔርን ባርኪ፤ ምስጋናውንም አትርሺ።', 1, 'ዘማሪ ዲ/ን ቴዎድሮስ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.793Z', '2026-10-17T17:56:56.793Z');
