INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('ed4862f5-95b4-483f-b279-5f55d6b52820', 'ጻድቁ አባታችን ተክለ ሃይማኖት', 'ተክለ ሃይማኖት ጸሎትህ አይለየን፤ በምልጃህ ጸንተን በበረከት እንኑር።', 5, 'ዘማሪት ፋንቱ ወልዴ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.703Z', '2026-10-17T17:56:56.703Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f276da5c-50a3-46bc-9b8e-c6142ab6c034', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው፤ የሚያስፈራኝ ማን ነው?', 3, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.734Z', '2026-10-17T17:56:56.734Z');
